const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define locations
  const graftonCoords = [152.9248, -28.9719]; // Grafton, NSW
  const canberraCoords = [149.1900, -35.2809]; // Canberra
  const graftonPoint = ee.Geometry.Point(graftonCoords);
  const canberraPoint = ee.Geometry.Point(canberraCoords);

  // Buffer to 1km to ensure valid pixels
  const graftonGeom = graftonPoint.buffer(1000);
  const canberraGeom = canberraPoint.buffer(1000);

  // 2. Date range: January 15, 2020 to January 21, 2020
  const startDate = '2020-01-15';
  const endDate = '2020-01-21';

  // 3. Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  // Check if collection has data
  const collectionSize = await chirps.size().getInfo();
  console.log(`CHIRPS Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No CHIRPS data available for this date range.');
    console.log('C1');
    process.exit();
  }

  // 4. Sum precipitation over the period
  const totalPrecipitation = chirps.reduce(ee.Reducer.sum());

  // 5. Calculate total rainfall for Grafton
  const graftonStats = await totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: graftonGeom,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const graftonRainfall = graftonStats.precipitation;

  // 6. Calculate total rainfall for Canberra
  const canberraStats = await totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: canberraGeom,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const canberraRainfall = canberraStats.precipitation;

  // 7. Validate results
  console.log(`Grafton Total Rainfall (Jan 15-21, 2020): ${graftonRainfall !== null ? graftonRainfall.toFixed(2) : 'N/A'} mm`);
  console.log(`Canberra Total Rainfall (Jan 15-21, 2020): ${canberraRainfall !== null ? canberraRainfall.toFixed(2) : 'N/A'} mm`);

  // Check for null or invalid values
  if (graftonRainfall === null || canberraRainfall === null || 
      isNaN(graftonRainfall) || isNaN(canberraRainfall)) {
    console.log('C3');
    process.exit();
  }

  // Check for invalid negative values
  if (graftonRainfall < 0 || canberraRainfall < 0) {
    console.log('C3');
    process.exit();
  }

  // 8. Determine if Grafton > Canberra
  if (graftonRainfall > canberraRainfall) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
